namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6–10 uppercase alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetCoursesByDepartment(int departmentId);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
        new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, civilizations, and their impact on the present." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Foundational course covering variables, control flow, functions, and object-oriented basics using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "PhD in Computer Science from MIT. 15 years of teaching experience in introductory programming and software engineering.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, and searching algorithms with complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Renowned researcher in algorithm design. Published over 40 papers on computational complexity.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Former industry database architect with 20 years at Oracle. Specializes in query optimization.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Isaac Newton", InstructorBio = "Award-winning educator specializing in making calculus accessible to first-year students.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Code = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Expert in abstract algebra with a passion for connecting theory to real-world applications.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Fundamentals of academic writing, argumentation, and critical reading strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Published author and writing instructor. Focuses on clarity, voice, and the craft of revision.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = false },
        new() { Id = 7, Code = "ENG 250", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Chinua Achebe", InstructorBio = "Comparative literature scholar with research interests in post-colonial narratives.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = true },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM, Lab: Fri 1:00–3:00 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Celebrated physics educator known for intuitive explanations and engaging demonstrations.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 9, Code = "PHYS 240", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. James Maxwell", InstructorBio = "Theoretical physicist focused on electrodynamics and optics. 10+ years of teaching.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, trade routes, and cultural exchange from antiquity to the early modern period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Herodotus Smith", InstructorBio = "Historian specializing in ancient civilizations and cross-cultural interactions.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = false },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        Courses.Where(c => c.DepartmentId == departmentId).ToList();
}

